"""Generate the synthetic DBF fixtures used by the conformance suite.

These fixtures are generated, not captured from FoxPro: they follow the
DBF layout of docs/formats.md byte-for-byte and are regenerated by this
script (spec §3.2 testdata/gen). Real-tool reference fixtures belong in
testdata/reference/ with PROVENANCE.txt entries (spec §8.9).
"""
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))


def dbf_bytes(fields, records, version=0x03, cp_mark=0x01, year=2025, month=1, day=15):
    """fields: list of (name, type, len, dec); records: list of (deleted, [raw field bytes])"""
    nf = len(fields)
    header_size = 32 + 32 * nf + 1
    rec_size = 1 + sum(f[2] for f in fields)
    hdr = bytearray(32)
    hdr[0] = version
    hdr[1] = year - 1900
    hdr[2] = month
    hdr[3] = day
    struct.pack_into("<I", hdr, 4, len(records))
    struct.pack_into("<H", hdr, 8, header_size)
    struct.pack_into("<H", hdr, 10, rec_size)
    hdr[29] = cp_mark
    out = bytearray(hdr)
    for name, typ, ln, dec in fields:
        d = bytearray(32)
        d[0:len(name)] = name.encode("ascii")
        d[11] = ord(typ)
        d[16] = ln
        d[17] = dec
        out += d
    out.append(0x0D)
    for deleted, vals in records:
        out.append(0x2A if deleted else 0x20)
        for v in vals:
            out += v
    out.append(0x1A)
    return bytes(out)


def c(s, ln):
    b = s.encode("cp437") if isinstance(s, str) else s
    return b[:ln].ljust(ln, b" ")


def n(x, ln, dec):
    s = ("%.*f" % (dec, x)) if dec else str(int(x))
    return s.encode("ascii").rjust(ln, b" ")


def d(y, m, dd):
    return ("%04d%02d%02d" % (y, m, dd)).encode("ascii")


def l(b):
    return (b"T" if b else b"F")


PEOPLE_FIELDS = [("NAME", "C", 20, 0), ("AGE", "N", 3, 0), ("BORN", "D", 8, 0),
                 ("MARRIED", "L", 1, 0), ("SCORE", "N", 6, 2)]

PEOPLE = [
    (False, [c("Alice", 20), n(30, 3, 0), d(1995, 3, 12), l(True), n(87.50, 6, 2)]),
    (False, [c("Bob", 20), n(25, 3, 0), d(2000, 2, 29), l(False), n(92.00, 6, 2)]),
    (False, [c("Carol", 20), n(41, 3, 0), d(1983, 7, 4), l(True), n(78.25, 6, 2)]),
    (True, [c("Dave", 20), n(35, 3, 0), d(1989, 11, 30), l(False), n(60.00, 6, 2)]),
    (False, [c("Eve", 20), n(28, 3, 0), d(1997, 1, 1), l(True), n(99.99, 6, 2)]),
]


MEMO_FIELDS = [("ID", "N", 4, 0), ("NOTES", "M", 10, 0)]

MEMO_TEXTS = [
    b"short note",
    b"a much longer memo that spans several 64-byte FPT blocks to exercise "
    b"multi-block allocation and in-place vs extend behavior on rewrite",
    b"",
]


def fpt_bytes(texts, bs=64):
    """Build an FPT file: 512-byte header (BE32 next-free, BE16 block size),
    then 8-byte block headers (BE32 type=0 text, BE32 length) + payload."""
    hdr = bytearray(512)
    blocks = []
    next_blk = (512 + bs - 1) // bs
    body = bytearray()
    for t in texts:
        off = next_blk * bs
        need = (8 + len(t) + bs - 1) // bs * bs
        blk = bytearray(need)
        blk[0:4] = len(t).to_bytes(4, "big")
        blk[4:8] = (0).to_bytes(4, "big") if False else b"\x00\x00\x00\x00"
        # FPT block header: type BE32 then length BE32
        blk[0:4] = (0).to_bytes(4, "big")
        blk[4:8] = len(t).to_bytes(4, "big")
        blk[8:8 + len(t)] = t
        blocks.append((next_blk, bytes(blk)))
        next_blk += need // bs
    struct.pack_into(">I", hdr, 0, next_blk)
    struct.pack_into(">H", hdr, 6, bs)
    out = bytearray(hdr)
    maxend = 512
    for blkno, blk in blocks:
        end = blkno * bs + len(blk)
        if end > maxend:
            maxend = end
    out += b"\x00" * (maxend - 512)
    for blkno, blk in blocks:
        out[blkno * bs:blkno * bs + len(blk)] = blk
    return bytes(out), [b[0] for b in blocks]


def dbt_bytes(texts, blk=512):
    """Build a dBase DBT: 512-byte header (LE32 next block at 0), then each
    memo as data + 0x1A padded to a 512 boundary (append-per-write)."""
    hdr = bytearray(blk)
    out = bytearray(hdr)
    blocks = []
    for t in texts:
        while len(out) % blk != 0:
            out += b"\x00"
        b = len(out) // blk
        blocks.append(b)
        out += t + b"\x1a"
        while len(out) % blk != 0:
            out += b"\x00"
    struct.pack_into("<I", out, 0, len(out) // blk)
    return bytes(out), blocks


def main():
    out = HERE
    with open(os.path.join(out, "people.dbf"), "wb") as f:
        f.write(dbf_bytes(PEOPLE_FIELDS, PEOPLE, version=0x03, cp_mark=0x01))
    with open(os.path.join(out, "empty.dbf"), "wb") as f:
        f.write(dbf_bytes(PEOPLE_FIELDS, [], version=0x03, cp_mark=0x01))
    # CP437 high-byte fixture: 0x82 = e-acute in CP437
    with open(os.path.join(out, "cp437.dbf"), "wb") as f:
        f.write(dbf_bytes([("TXT", "C", 10, 0)],
                          [(False, [c(b"caf\x82", 10)])], version=0x30, cp_mark=0x01))
    # FoxPro-version (0x30) variant of people for version-byte coverage
    with open(os.path.join(out, "people30.dbf"), "wb") as f:
        f.write(dbf_bytes(PEOPLE_FIELDS, PEOPLE, version=0x30, cp_mark=0x03))
    # fuzz seeds: tiny malformed inputs for the libFuzzer corpus
    seeds = os.path.join(out, "fuzz-seeds")
    os.makedirs(seeds, exist_ok=True)
    with open(os.path.join(seeds, "truncated-header.dbf"), "wb") as f:
        f.write(b"\x03\x19\x01\x0f\x05\x00")
    with open(os.path.join(seeds, "bad-magic.dbf"), "wb") as f:
        f.write(b"\x99" + b"\x00" * 100)
    with open(os.path.join(seeds, "zero-fields.dbf"), "wb") as f:
        f.write(dbf_bytes([], []))
    with open(os.path.join(seeds, "empty.dbf"), "wb") as f:
        f.write(b"")
    # empty table with the people layout (write tests APPEND into it)
    with open(os.path.join(out, "blank.dbf"), "wb") as f:
        f.write(dbf_bytes(PEOPLE_FIELDS, [], version=0x03, cp_mark=0x01))
    # FoxPro memo fixture: version 0xF5 + FPT sidecar (block size 64)
    memo_blocks = [b"%10d" % b for b in [0, 0, 0]]
    fpt, blks = fpt_bytes(MEMO_TEXTS)
    recs = []
    for i, t in enumerate(MEMO_TEXTS):
        blkno = blks[i] if t else 0
        recs.append((i == 2, [n(i + 1, 4, 0), b"%10d" % blkno]))
    with open(os.path.join(out, "memo.dbf"), "wb") as f:
        f.write(dbf_bytes(MEMO_FIELDS, recs, version=0xF5, cp_mark=0x01))
    with open(os.path.join(out, "memo.fpt"), "wb") as f:
        f.write(fpt)
    # dBase III memo fixture: version 0x83 + DBT sidecar
    dbt, dblks = dbt_bytes([b"dbt one", b"dbt two, a bit longer"])
    drecs = [(False, [n(1, 4, 0), b"%10d" % dblks[0]]),
             (False, [n(2, 4, 0), b"%10d" % dblks[1]])]
    with open(os.path.join(out, "dbtmemo.dbf"), "wb") as f:
        f.write(dbf_bytes(MEMO_FIELDS, drecs, version=0x83, cp_mark=0x01))
    with open(os.path.join(out, "dbtmemo.dbt"), "wb") as f:
        f.write(dbt)
    print("fixtures written to", out)


if __name__ == "__main__":
    sys.exit(main())
